From dd18852bc4a0943b2b1e8b7e59a5f216f3e81cad Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:56:51 +0100
Subject: [PATCH] applet: don't show two expanded lines when switching panel
 popups

A new popup's line appeared before its window was shown, while the old
line stayed until a 100 ms timer collapsed its popup. Now the line only
shows while the popup is visible and after it has been activated.

BUG: 517066
---
 desktoppackage/contents/applet/CompactApplet.qml | 10 +++++++++-
 1 file changed, 9 insertions(+), 1 deletion(-)

diff --git a/desktoppackage/contents/applet/CompactApplet.qml b/desktoppackage/contents/applet/CompactApplet.qml
index 1aba2a5cd9..1044a22812 100644
--- a/desktoppackage/contents/applet/CompactApplet.qml
+++ b/desktoppackage/contents/applet/CompactApplet.qml
@@ -151,7 +151,7 @@ PlasmaCore.ToolTipArea {
             }
             return prefix;
         }
-        opacity: root.plasmoidItem.expanded ? 1 : 0
+        opacity: root.plasmoidItem.expanded && dialog.visible && dialog.wasActive ? 1 : 0
         Behavior on opacity {
             NumberAnimation {
                 duration: Kirigami.Units.shortDuration
@@ -220,9 +220,17 @@ PlasmaCore.ToolTipArea {
         appletInterface: root.plasmoidItem

         property var oldStatus: PlasmaCore.Types.UnknownStatus
+        property bool wasActive: false
+
+        onActiveChanged: {
+            if (active) {
+                wasActive = true;
+            }
+        }

         onVisibleChanged: {
             if (!visible) {
+                wasActive = false;
                 expandedSync.restart();
                 Plasmoid.status = oldStatus;
             } else {
-- 
